```st
FUNCTION_BLOCK FB
VAR_INPUT
    Mode            : BOOL;
    ForwardButton   : BOOL;
    ReverseButton   : BOOL;
    SensorFeed      : BOOL;
    SensorWash      : BOOL;
    SensorWeight    : BOOL;
    SensorFiring    : BOOL;
    SensorOutput    : BOOL;
    washComplete    : BOOL;
    weightComplete  : BOOL;
    weight          : REAL;
    firingComplete  : BOOL;
END_VAR
VAR_OUTPUT
    MotorForward    : BOOL;
    MotorReverse    : BOOL;
    kick            : BOOL;
    CompletionLight : BOOL;
    firingTemp      : REAL;
END_VAR
VAR
    iState      : INT;
    prevMode    : BOOL;
    prevForward : BOOL;
    prevReverse : BOOL;
END_VAR

TYPE EState : INT (
    IDLE       := 0;
    FEEDING    := 1;
    WASHING    := 2;
    WEIGHING   := 3;
    FIRING     := 4;
    TO_OUTPUT  := 5;
    COMPLETED  := 6;
    REJECTING  := 7
) END_TYPE

MotorForward    := FALSE;
MotorReverse    := FALSE;
kick            := FALSE;
CompletionLight := FALSE;

IF NOT Mode THEN
    prevForward := ForwardButton;
    prevReverse := ReverseButton;

    IF ForwardButton AND NOT ReverseButton THEN
        MotorForward := TRUE;
        MotorReverse := FALSE;
    ELSIF ReverseButton AND NOT ForwardButton THEN
        MotorForward := FALSE;
        MotorReverse := TRUE;
    ELSE
        MotorForward := FALSE;
        MotorReverse := FALSE;
    END_IF

    iState := IDLE;
ELSE
    IF NOT prevMode THEN
        kick := FALSE;
        IF SensorFeed THEN
            iState := FEEDING;
            MotorForward := TRUE;
        END_IF
    END_IF

    IF iState = IDLE THEN
        MotorForward := FALSE;
        MotorReverse := FALSE;
        IF SensorFeed THEN
            iState := FEEDING;
            MotorForward := TRUE;
        END_IF;

    ELSIF iState = FEEDING THEN
        MotorReverse := FALSE;
        IF SensorWash THEN
            iState := WASHING;
            MotorForward := FALSE;
        END_IF;

    ELSIF iState = WASHING THEN
        MotorForward := FALSE;
        MotorReverse := FALSE;
        IF washComplete THEN
            iState := FEEDING;
            MotorForward := TRUE;
        END_IF;

    ELSIF iState = WEIGHING THEN
        MotorForward := FALSE;
        MotorReverse := FALSE;
        IF weightComplete THEN
            IF weight >= 100.0 AND weight <= 200.0 THEN
                firingTemp := 500.0 + (weight - 100.0) * 0.5;
                kick := FALSE;
                MotorForward := TRUE;
                iState := FIRING;
            ELSE
                MotorForward := FALSE;
                kick := TRUE;
                iState := REJECTING;
            END_IF;
        END_IF;

    ELSIF iState = FIRING THEN
        MotorForward := FALSE;
        MotorReverse := FALSE;
        IF firingComplete THEN
            MotorForward := TRUE;
            iState := TO_OUTPUT;
        END_IF;

    ELSIF iState = TO_OUTPUT THEN
        IF SensorOutput THEN
            MotorForward := FALSE;
            MotorReverse := FALSE;
            CompletionLight := TRUE;
            iState := COMPLETED;
        END_IF;

    ELSIF iState = COMPLETED THEN
        MotorForward := FALSE;
        MotorReverse := FALSE;
        IF NOT SensorOutput THEN
            CompletionLight := FALSE;
            iState := IDLE;
            firingTemp := 0.0;
        END_IF;

    ELSIF iState = REJECTING THEN
        MotorForward := FALSE;
        MotorReverse := FALSE;
        kick := TRUE;
        IF NOT SensorOutput THEN
            kick := FALSE;
            iState := IDLE;
        END_IF;
    END_IF;
END_IF;

prevMode := Mode;
END_FUNCTION_BLOCK
```

